import{_ as a,o as t,c as n,ag as o}from"./chunks/framework.DTisvaUJ.js";const g=JSON.parse('{"title":"Changelog","description":"Mutelink release history: major updates and fixes for recognition, speech synthesis, translation and VR keyboards.","frontmatter":{"description":"Mutelink release history: major updates and fixes for recognition, speech synthesis, translation and VR keyboards.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/en/about/changelog"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Changelog | Mutelink"}],["meta",{"property":"og:description","content":"Mutelink release history: major updates and fixes for recognition, speech synthesis, translation and VR keyboards."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/en/about/changelog"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Changelog | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelink release history: major updates and fixes for recognition, speech synthesis, translation and VR keyboards."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/about/changelog"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/about/changelog"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/about/changelog"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/about/changelog"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/about/changelog"}]]},"headers":[],"relativePath":"en/about/changelog.md","filePath":"en/about/changelog.md"}'),r={name:"en/about/changelog.md"};function i(l,e,s,h,u,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="更新履歴" tabindex="-1">Changelog <a class="header-anchor" href="#更新履歴" aria-label="Permalink to &quot;Changelog {#更新履歴}&quot;">​</a></h1><p>Major changes only, newest first. Installers are on <a href="https://github.com/utyujinn/Mutelink-releases/releases" target="_blank" rel="noreferrer">Releases</a>.</p><h2 id="v2-0-0-2026年11月15日" tabindex="-1">v2.0.0 (November 15, 2026) <a class="header-anchor" href="#v2-0-0-2026年11月15日" aria-label="Permalink to &quot;v2.0.0 (November 15, 2026) {#v2-0-0-2026年11月15日}&quot;">​</a></h2><p>A major redesign of the interface and features.</p><h3 id="画面" tabindex="-1">Interface <a class="header-anchor" href="#画面" aria-label="Permalink to &quot;Interface {#画面}&quot;">​</a></h3><ul><li>Completely redesigned the interface and controls.</li></ul><h3 id="読み上げ" tabindex="-1">Speech synthesis <a class="header-anchor" href="#読み上げ" aria-label="Permalink to &quot;Speech synthesis {#読み上げ}&quot;">​</a></h3><ul><li>Greatly reduced Irodori-TTS VRAM use and improved speed.</li><li>Added Qwen3-TTS for Japanese and nine other languages (<a href="/Mutelink-releases/en/compare/voices">voice samples</a>).</li></ul><h3 id="音声認識" tabindex="-1">Speech recognition <a class="header-anchor" href="#音声認識" aria-label="Permalink to &quot;Speech recognition {#音声認識}&quot;">​</a></h3><ul><li>Updated local recognition models, greatly improving Japanese recognition (Parakeet Japanese TDT, Haas-ja, Qwen3-ASR; <a href="/Mutelink-releases/en/compare/speech-recognition">comparison</a>).</li></ul><h3 id="翻訳" tabindex="-1">Translation <a class="header-anchor" href="#翻訳" aria-label="Permalink to &quot;Translation {#翻訳}&quot;">​</a></h3><ul><li>Translate your words and send them as speech or chatbox text.</li><li>Read translations of incoming speech.</li><li>Choose PLaMo, TranslateGemma or cloud-based Azure Translator (<a href="/Mutelink-releases/en/compare/translation">comparison</a>).</li></ul><h3 id="vrキーボード" tabindex="-1">VR keyboard <a class="header-anchor" href="#vrキーボード" aria-label="Permalink to &quot;VR keyboard {#vrキーボード}&quot;">​</a></h3><ul><li>Input methods for Japanese (4), Chinese (4), Korean (2), English, symbols and templates.</li><li>Added glide input.</li></ul><h3 id="そのほか" tabindex="-1">Other changes <a class="header-anchor" href="#そのほか" aria-label="Permalink to &quot;Other changes {#そのほか}&quot;">​</a></h3><ul><li>Added an optional feature that waits to speak while someone else is talking.</li><li>Chatbox text can appear when speech starts (optional).</li><li>Separated the control panel from the keyboard and allowed hand attachment (Customization extension required).</li></ul><h2 id="v1-0-3-2026年11月5日" tabindex="-1">v1.0.3 (November 5, 2026) <a class="header-anchor" href="#v1-0-3-2026年11月5日" aria-label="Permalink to &quot;v1.0.3 (November 5, 2026) {#v1-0-3-2026年11月5日}&quot;">​</a></h2><ul><li>Fixed overlapping or missing audio with Parakeet, Whisper and Google recognition.</li></ul><h2 id="v1-0-2-2026年10月18日" tabindex="-1">v1.0.2 (October 18, 2026) <a class="header-anchor" href="#v1-0-2-2026年10月18日" aria-label="Permalink to &quot;v1.0.2 (October 18, 2026) {#v1-0-2-2026年10月18日}&quot;">​</a></h2><ul><li>Allowed customizing the lower thumb button’s single-press action.</li><li>Added anonymous feedback to report bugs and requests.</li><li>Show changes on the first launch after an update.</li><li>Show an error message when an operation fails.</li></ul><h2 id="v1-0-1-2026年10月16日" tabindex="-1">v1.0.1 (October 16, 2026) <a class="header-anchor" href="#v1-0-1-2026年10月16日" aria-label="Permalink to &quot;v1.0.1 (October 16, 2026) {#v1-0-1-2026年10月16日}&quot;">​</a></h2><ul><li>Fixed adding and loading VR background images.</li><li>Added the option to check for updates at startup.</li></ul><h2 id="v1-0-0-2026年10月10日" tabindex="-1">v1.0.0 (October 10, 2026) <a class="header-anchor" href="#v1-0-0-2026年10月10日" aria-label="Permalink to &quot;v1.0.0 (October 10, 2026) {#v1-0-0-2026年10月10日}&quot;">​</a></h2><p>First stable release.</p>',24)])])}const p=a(r,[["render",i]]);export{g as __pageData,p as default};
